const __aivicBundle_48_detectScheduleDelayAndAlert = (() => {
  interface DetectScheduleDelayAndAlertInput {
    phaseId: string;
    phaseLabel: string;
    deadline: Date;
    currentTime: Date;
  }
  
  interface DetectScheduleDelayAndAlertLogEntry {
    eventType: string;
    phaseId: string;
    deadline: Date;
    detectedAt: Date;
  }
  
  interface DetectScheduleDelayAndAlertResult {
    isDelayed: boolean;
    delayMinutes: number;
    alertTriggered: boolean;
    alertMessage: string;
    alertLevel: string;
    eventLogged: boolean;
    logEntry: DetectScheduleDelayAndAlertLogEntry;
    delayMilliseconds: number;
    checkExecutedWithinSLA: boolean;
    checkExecutionTimeMs: number;
  }
  
   function detectScheduleDelayAndAlert(
    input: DetectScheduleDelayAndAlertInput
  ): DetectScheduleDelayAndAlertResult {
    const { phaseId, phaseLabel, deadline, currentTime } = input;
  
    const delayMilliseconds = currentTime.getTime() - deadline.getTime();
    const delayMinutes = Math.floor(delayMilliseconds / (1000 * 60));
    const isDelayed = delayMilliseconds > 0;
  
    const alertTriggered = isDelayed;
    const alertMessage = isDelayed
      ? `${phaseLabel}の納期を${delayMinutes}分超過しています`
      : '';
    const alertLevel = isDelayed ? 'WARNING' : 'OK';
  
    const logEntry: DetectScheduleDelayAndAlertLogEntry = {
      eventType: 'SCHEDULE_DELAY_DETECTED',
      phaseId,
      deadline,
      detectedAt: currentTime,
    };
  
    const checkExecutionTimeMs = 0;
    const checkExecutedWithinSLA = checkExecutionTimeMs <= 300000;
  
    return {
      isDelayed,
      delayMinutes,
      alertTriggered,
      alertMessage,
      alertLevel,
      eventLogged: true,
      logEntry,
      delayMilliseconds,
      checkExecutedWithinSLA,
      checkExecutionTimeMs,
    };
  }
  return { detectScheduleDelayAndAlert };
})();
